// Generated by philote from page /projects. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { projects } from "@/lib/api";
import { must } from "@/lib/backend";
import { readProjectCard } from "@/lib/reads";

import ProjectCard from "@/components/common/project-card";

export const metadata: Metadata = { title: "Projects" };

export default function Page() {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl space-y-6">
                <h1 className="font-heading text-4xl">{"Projects"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Records />
                </Suspense>
            </div>
        </main>
    );
}

async function Records() {
    await connection();
    const records = await must(projects.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No projects yet. Start one."}</p>;
    }
    const items = await Promise.all(records.map(readProjectCard));
    return (
        <div className="grid gap-4 md:grid-cols-2">
            {items.map((item) => (
                <ProjectCard key={item.project.id} {...item} />
            ))}
        </div>
    );
}
